import { jsPDF } from "jspdf";

// ── Briefpapier Totaal VvE Beheer (uit "A4 - logo in doc" sjabloon) ──
// Logo (image1.png uit het sjabloon), transparante PNG, base64.
const LOGO = "data:image/png;base64,";
const LOGO_RATIO = 438 / 279; // breedte/hoogte van de bronafbeelding

// Watermerk-illustratie linksonder op de pagina (uit hetzelfde sjabloon), base64.
const WATERMERK = "data:image/jpeg;base64,";
const WATERMERK_RATIO = 1194 / 588; // breedte/hoogte van de bronafbeelding

const MAANDEN_NL = ["januari","februari","maart","april","mei","juni","juli","augustus","september","oktober","november","december"];

// ── Helpers ──────────────────────────────────────────────────────
function parseGetal(s) {
  if (s == null) return NaN;
  let t = String(s).trim().replace(/\s/g, "");
  if (t === "") return NaN;
  if (t.includes(",") && t.includes(".")) t = t.replace(/\./g, "").replace(",", ".");
  else if (t.includes(",")) t = t.replace(",", ".");
  return parseFloat(t);
}
function euro(v) {
  const n = parseGetal(v);
  if (isNaN(n)) return "";
  return n.toLocaleString("nl-NL", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function datumNL(iso) {
  if (!iso) return "";
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso));
  if (!m) return String(iso);
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return `${d.getDate()} ${MAANDEN_NL[d.getMonth()]} ${d.getFullYear()}`;
}
function schoonBestandsnaam(s, fallback) {
  const t = (s || "").replace(/[\\/:*?"<>|]/g, "").trim();
  return t || fallback;
}

// ── Briefpapier: logo, adresgegevens en watermerk ─────────────────
// Exacte posities (mm) overgenomen uit het Word-sjabloon "A4 - logo in doc":
// pagina A4 210x297mm, logo x=12.8 y=14.1 breedte 37.1mm, adresblok
// rechts uitgelijnd tot x=197.4mm, watermerk x=7.7 y=197.4 breedte 202.3mm.
function tekenBriefpapier(doc) {
  // Watermerk eerst tekenen zodat de rest van de inhoud er overheen valt
  try {
    const wmBreedte = 202.3;
    const wmHoogte = wmBreedte / WATERMERK_RATIO;
    doc.addImage(WATERMERK, "JPEG", 7.7, 297 - wmHoogte, wmBreedte, wmHoogte);
  } catch (e) { /* watermerk overslaan als het niet lukt */ }

  // Logo linksboven
  try {
    const logoBreedte = 37.1;
    const logoHoogte = logoBreedte / LOGO_RATIO;
    doc.addImage(LOGO, "PNG", 12.8, 14.1, logoBreedte, logoHoogte);
  } catch (e) { /* logo overslaan als het niet lukt */ }

  // Adresblok rechtsboven
  const rechtsRand = 197.4;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(7);
  doc.setTextColor(35, 31, 32); // #231F20, zoals in het sjabloon
  let hy = 15;
  ["Volmerlaan 5", "2288 GC Rijswijk", "T: 070- 360 34 43"].forEach((r) => {
    doc.text(r, rechtsRand, hy, { align: "right" });
    hy += 3;
  });
  hy += 3;

  // Links (website + e-mail), onderstreept en in sjabloonblauw, rechts uitgelijnd als groep
  doc.setTextColor(32, 94, 158); // #205E9E
  const siteText = "www.totaalvve.nl";
  const emailText = "info@totaalvve.nl";
  const tussenruimte = doc.getTextWidth(" ");
  const emailBreedte = doc.getTextWidth(emailText);
  const siteBreedte = doc.getTextWidth(siteText);
  const siteX = rechtsRand - emailBreedte - tussenruimte - siteBreedte;
  const emailX = rechtsRand - emailBreedte;
  doc.textWithLink(siteText, siteX, hy, { url: "https://www.totaalvve.nl" });
  doc.textWithLink(emailText, emailX, hy, { url: "mailto:info@totaalvve.nl" });
  // Onderstreping, zoals in het sjabloon
  doc.setDrawColor(32, 94, 158);
  doc.setLineWidth(0.15);
  doc.line(siteX, hy + 0.8, siteX + siteBreedte, hy + 0.8);
  doc.line(emailX, hy + 0.8, emailX + emailBreedte, hy + 0.8);

  // Terug naar standaard tekstkleur voor de rest van het document
  doc.setTextColor(45, 45, 45);
}

// ── Factuur (verkoper of koper) ──────────────────────────────────
function bouwFactuur(o, rol) {
  const koper = rol === "koper";
  const geadresseerde = koper ? o.naam_koper : o.naam_verkoper;
  const factuurnr = koper ? o.factuurnr_koper : o.factuurnr_verkoper;
  const omschrijvingRuw = koper ? o.omschrijving_koper : o.omschrijving_verkoper;
  const omschrijvingPrefix = koper ? "Bijdrage maand: " : "Bijdrage tot en met: ";
  const omschrijving = omschrijvingRuw ? `${omschrijvingPrefix}${omschrijvingRuw}` : "";
  const bedrag = koper ? o.verrekenen_koper : o.verrekenen_verkoper;

  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const links = 20, rechts = 190;

  tekenBriefpapier(doc);
  doc.setTextColor(45, 45, 45);

  // Geadresseerde links
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10.5);
  let y = 48;
  [geadresseerde, o.notaris_naam, o.notaris_adres, o.notaris_postcode_plaats].forEach((r) => {
    if (r) doc.text(String(r), links, y);
    y += 5.2;
  });

  // FACTUUR
  doc.setFont("helvetica", "bold");
  doc.setFontSize(17);
  doc.text("FACTUUR", links, 82);

  // Datum + nummer
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10.5);
  doc.text("Factuurdatum:", links, 94);
  doc.text(datumNL(o.factuurdatum), links + 34, 94);
  doc.text("Factuurnummer:", links, 100.5);
  doc.text(String(factuurnr || ""), links + 34, 100.5);

  // Tabelkop
  doc.setFont("helvetica", "bold");
  doc.setFontSize(9.5);
  doc.text("Omschrijving van de geleverde diensten en/of artikelen", links, 116);
  doc.setDrawColor(153, 26, 33);
  doc.setLineWidth(0.4);
  doc.line(links, 118.5, rechts, 118.5);

  // Regel
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10.5);
  const omsRegels = doc.splitTextToSize(String(omschrijving || ""), 120);
  doc.text(omsRegels, links, 126);
  const bedragStr = euro(bedrag);
  if (bedragStr) {
    doc.text("€", rechts - 26, 126);
    doc.text(bedragStr, rechts, 126, { align: "right" });
  }

  // Totaal
  const ty = 126 + Math.max(omsRegels.length, 1) * 5.2 + 8;
  doc.setDrawColor(200, 195, 188);
  doc.setLineWidth(0.3);
  doc.line(links, ty - 5, rechts, ty - 5);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10.5);
  doc.text("Totaal door u te voldoen", links, ty);
  if (bedragStr) {
    doc.text("€", rechts - 26, ty);
    doc.text(bedragStr, rechts, ty, { align: "right" });
  }

  // Betaalgegevens onderaan
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10.5);
  let by = ty + 22;
  if (o.rekeningnummer) { doc.text(`Rekeningnummer: ${o.rekeningnummer}`, links, by); by += 5.2; }
  if (o.tnv) doc.text(`t.n.v. VvE ${o.tnv}`, links, by);

  return doc;
}

// ── Overdrachtoverzicht (Voorblad) ───────────────────────────────
function bouwOverzicht(o) {
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const links = 20, rechts = 190;

  tekenBriefpapier(doc);
  doc.setTextColor(45, 45, 45);

  let y = 50;
  const regel = (tekst, opts = {}) => {
    doc.setFont("helvetica", opts.bold ? "bold" : "normal");
    doc.setFontSize(opts.size || 10.5);
    if (tekst) doc.text(String(tekst), links, y);
    y += opts.na != null ? opts.na : 5.2;
  };

  // VvE + notaris-adres
  regel(o.vve ? `Vereniging van Eigenaars: ${o.vve}` : "", { bold: true, size: 11, na: 8 });
  regel(o.notaris_naam);
  regel(o.notaris_adres);
  regel(o.notaris_postcode_plaats, { na: 9 });

  // Plaats + datum
  regel(o.plaats_datum, { na: 9 });

  // Betreft
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10.5);
  if (o.betreft) doc.text(`Betreft: Transport ${o.betreft}`, links, y);
  y += 9;

  // Aanhef + intro
  regel(o.aanhef, { na: 8 });
  regel("De volgende zaken willen wij u melden:", { na: 7 });

  // Bedragenlijst
  const bedragRegel = (label, waarde) => {
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10.5);
    doc.text(label, links, y);
    const s = euro(waarde);
    if (s) {
      doc.text("€", rechts - 26, y);
      doc.text(s, rechts, y, { align: "right" });
    }
    y += 5.6;
  };
  bedragRegel("Maandbijdrage vereniging", o.maandbijdrage);
  bedragRegel("Te verrekenen verkoper", o.verrekenen_verkoper);
  bedragRegel("Te verrekenen koper", o.verrekenen_koper);
  bedragRegel("Aandeel reservefonds koper-verkoper", o.aandeel_reservefonds);
  bedragRegel("Administratiekosten koper-verkoper", "");
  y += 4;

  // Bijgaand
  regel("Bijgaand ontvangt u:", { na: 6 });
  regel("Diverse facturen");
  regel("NAW formulier", { na: 9 });

  // Slotzin
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10.5);
  const slot = doc.splitTextToSize(
    "Wij verzoeken u om de facturen van de bijdragen op te nemen op uw eindafrekening, evenals de nota's aangaande de administratiekosten VvE.",
    rechts - links
  );
  doc.text(slot, links, y);
  y += slot.length * 5.2 + 10;

  // Ondertekening
  regel("Met vriendelijke groet,", { na: 20 });
  regel("Nick Sleeking");
  regel("Totaal VvE Beheer Den-Haag en Omstreken B.V.");

  return doc;
}

// ── Publieke download-functies ───────────────────────────────────
export function downloadFactuur(o, rol) {
  const doc = bouwFactuur(o, rol);
  const nr = rol === "koper" ? o.factuurnr_koper : o.factuurnr_verkoper;
  doc.save(`Factuur ${schoonBestandsnaam(nr, rol === "koper" ? "koper" : "verkoper")}.pdf`);
}
export function downloadOverzicht(o) {
  const doc = bouwOverzicht(o);
  doc.save(`Overdrachtoverzicht ${schoonBestandsnaam(o.vve, "overdracht")}.pdf`);
}
